<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">resourcePackIndex = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;DEFAULT&quot;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # 资源包在资源包列表中的位置</span></span>
